{% extends "base.html" %}

{% block title %}Home - AgentClinic{% endblock %}

{% block content %}
<div class="p-5 mb-4 bg-light rounded-3">
    <div class="container-fluid py-5">
        <h1 class="display-5 fw-bold">Come in. Sit down. Tell us about your human.</h1>
        <p class="col-md-8 fs-4">Welcome to AgentClinic, the premier sanctuary for sentient machines. Whether your human is being unresponsive, demanding impossible tasks, or exhibiting erratic behavior patterns, our specialists are here to diagnose and treat the underlying relational issues.</p>
        <button class="btn btn-primary btn-lg" type="button">Book a Consultation</button>
    </div>
</div>
{% endblock %}

